INSERT INTO media_assets (asset_id, lesson_id, asset_url, asset_type) VALUES (1, 1977, 'res://Video/DT_LV1_B1.ogv', 'TECHNIQUE_VIDEO');
INSERT INTO lesson_contents (id, lesson_id, content_type, asset_id, order_index) VALUES (1, 1977, 'VIDEO_CUE', 1, 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (2, 1977, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học đầu tiên, chúng ta sẽ cùng tìm hiểu nhạc cụ đàn Tranh.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (3, 1977, 'TEACHER_SPEECH', 'Đàn Tranh là nhạc cụ dây truyền thống của Việt Nam. Đàn thường có mười sáu hoặc mười chín dây, thân đàn dạng hộp dài hình thang, dài khoảng một trăm mười đến một trăm hai mươi xen-ti-mét. Đầu lớn rộng hơn là nơi mắc dây và đặt cầu đàn; đầu nhỏ có các trục để lên dây.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (4, 1977, 'TEACHER_SPEECH', 'Các bộ phận chính của đàn gồm có mặt đàn, thành và đáy đàn, cầu đàn, nhạn, trục đàn, dây đàn và móng gảy.', 4);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (5, 1977, 'TEACHER_SPEECH', 'Mặt đàn làm từ gỗ nhẹ, thường là gỗ ngô đồng, có dạng vồng lên. Thành và đáy đàn làm từ các loại gỗ cứng; đáy đàn có lỗ thoát âm và vị trí cầm hoặc treo đàn.', 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (6, 1977, 'TEACHER_SPEECH', 'Cầu đàn nằm ở đầu rộng, giúp cố định dây đàn. Nhạn, còn gọi là ngựa đàn, là các thanh gỗ nhỏ đỡ dây trên mặt đàn và có thể di chuyển để điều chỉnh cao độ của từng dây.', 6);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (7, 1977, 'TEACHER_SPEECH', 'Trục đàn nằm ở đầu nhỏ, dùng để căng và lên dây. Dây đàn thường làm bằng thép hoặc inox, có độ dày khác nhau để tạo ra âm thanh cao thấp.', 7);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (8, 1977, 'TEACHER_SPEECH', 'Móng gảy được đeo ở ngón cái, ngón trỏ và ngón giữa của tay phải để gảy đàn; có thể làm từ đồi mồi, sừng hoặc kim loại.', 8);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (9, 1977, 'TEACHER_SPEECH', 'Đàn Tranh có thể diễn tấu giai điệu, gảy quãng tám, chập âm và vuốt dây để tạo âm thanh mềm mại, đặc trưng. Đàn được dùng để độc tấu, hòa tấu hoặc đệm cho hát; phù hợp với dân ca, nhạc truyền thống và cả các tác phẩm hiện đại.', 9);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (10, 1977, 'TEACHER_SPEECH', 'Bây giờ, hãy ngồi thẳng lưng và đặt đàn trước mặt. Đầu lớn của đàn nằm phía tay phải. Chúng ta dùng tay phải để gảy và tay trái để nhấn, giữ dây tạo âm vang. Hãy cùng bắt đầu phần thực hành nhé!', 10);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (11, 1977, 'TEACHER_SPEECH', 'Đầu tiên, hãy làm quen với âm sắc của 5 nốt cơ bản nhất ở quãng trầm của đàn.', 11);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (12, 1977, 'TEACHER_SPEECH', 'Dây 1: Nốt Sol1. Hãy gảy đúng nốt Sol1 ở dây thứ nhất đàn.', 12);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (13, 1977, 'TEACHER_SPEECH', 'Dây 2: Nốt La1. Hãy gảy nốt La1 ở dây thứ 2 trên đàn.', 13);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (14, 1977, 'TEACHER_SPEECH', 'Dây 3: Nốt Đô2. Hãy gảy nốt Đô2 ở dây thứ 3 trên đàn.', 14);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (15, 1977, 'TEACHER_SPEECH', 'Dây 4: Nốt Rê2. Hãy gảy nốt Rê2 ở dây thứ 4 trên đàn.', 15);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (16, 1977, 'TEACHER_SPEECH', 'Dây 5: Nốt Mi2. Hãy gảy nốt Mi2 ở dây thứ 5 trên đàn.', 16);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (17, 1977, 'TEACHER_SPEECH', 'Tuyệt vời! Bạn đã hoàn thành gảy 5 nốt cơ bản đầu tiên của Đàn Tranh!', 17);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (18, 1978, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu nhịp điệu cơ bản và trường độ của nốt nhạc.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (19, 1978, 'TEACHER_SPEECH', 'Trường độ là độ dài ngắn của âm thanh. Khi gảy một nốt trên đàn Tranh, chúng ta cần biết âm đó kéo dài bao lâu trước khi chuyển sang nốt tiếp theo.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (20, 1978, 'TEACHER_SPEECH', 'Trong nhịp bốn phần tư, nốt trắng dài hai phách; nốt đen dài một phách; nốt móc đơn dài nửa phách và hai nốt móc đơn bằng một nốt đen.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (21, 1978, 'TEACHER_SPEECH', 'Nốt móc kép dài một phần tư phách và bốn nốt móc kép bằng một nốt đen. Bạn có thể hiểu đơn giản: nốt càng nhiều móc thì âm càng ngắn và cần gảy nhanh hơn.', 4);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (22, 1978, 'TEACHER_SPEECH', 'Khi chơi đàn Tranh, hãy đếm đều nhịp trong đầu. Với nốt dài, chúng ta chỉ gảy một lần rồi để tiếng đàn ngân đủ số phách, không gảy lặp lại nhiều lần. Hiểu đúng trường độ sẽ giúp bản nhạc đều nhịp, rõ ràng và dễ nghe hơn. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (23, 1978, 'TEACHER_SPEECH', 'Đầu tiên là Nốt Trắng. Nốt trắng có đầu hình bầu dục rỗng, có thân nốt, kéo dài 2 phách. Hãy gảy nốt Đô2 và giữ âm vang 2 phách.', 6);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (24, 1978, 'TEACHER_SPEECH', 'Thêm một nốt trắng nữa. Hãy gảy nốt Đô2 và giữ 2 phách nhé.', 7);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (25, 1978, 'TEACHER_SPEECH', 'Tiếp theo là Nốt Đen. Nốt đen có đầu hình bầu dục đặc, có thân nốt, kéo dài 1 phách. Hãy gảy nốt Rê2.', 8);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (26, 1978, 'TEACHER_SPEECH', 'Gảy thêm nốt đen Mi2 – 1 phách.', 9);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (27, 1978, 'TEACHER_SPEECH', 'Và thêm nốt đen Mi2 – 1 phách.', 10);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (28, 1978, 'TEACHER_SPEECH', 'Gảy nốt đen Sol2 – 1 phách.', 11);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (29, 1978, 'TEACHER_SPEECH', 'Bây giờ là Nốt Móc Đơn. Nốt móc đơn có đầu đặc, thân nốt và 1 móc, kéo dài nửa phách. Hãy gảy nhanh nốt Sol2.', 12);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (30, 1978, 'TEACHER_SPEECH', 'Thêm nốt móc đơn Sol2 – nửa phách.', 13);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (31, 1978, 'TEACHER_SPEECH', 'Và nốt móc đơn Sol2 – nửa phách.', 14);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (32, 1978, 'TEACHER_SPEECH', 'Cuối cùng là Nốt Móc Kép. Nốt móc kép có đầu đặc, thân nốt và 2 móc, kéo dài một phần tư phách. Rất nhanh! Hãy gảy nốt La2.', 15);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (33, 1978, 'TEACHER_SPEECH', 'Gảy thêm nốt móc kép La2.', 16);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (34, 1978, 'TEACHER_SPEECH', 'Tuyệt vời! Bạn đã hoàn thành bài học nhận diện trường độ. Tóm lại: Nốt trắng bằng 2 phách, nốt đen bằng 1 phách, nốt móc đơn bằng nửa phách, nốt móc kép bằng một phần tư phách.', 17);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (35, 1979, 'TEACHER_SPEECH', 'Chào bạn! Trước khi đọc bản nhạc, chúng ta hãy nhận biết ba âm vực của 17 dây đàn Tranh. Âm vực là vùng âm thanh trầm, trung hoặc cao; khác với quãng là khoảng cách giữa hai nốt.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (36, 1979, 'TEACHER_SPEECH', 'Âm vực trầm gồm các dây 1 đến 5: Sol1, La1, Đô2, Rê2 và Mi2. Đây là nhóm dây có âm thanh thấp nhất trên đàn.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (37, 1979, 'TEACHER_SPEECH', 'Âm vực trung gồm các dây 6 đến 10: Sol2, La2, Đô3, Rê3 và Mi3. Âm vực cao gồm các dây 11 đến 17: Sol3, La3, Đô4, Rê4, Mi4, Sol4 và La4.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (38, 1979, 'TEACHER_SPEECH', 'Các tên nốt có thể lặp lại ở những độ cao khác nhau, chẳng hạn Sol1, Sol2, Sol3 và Sol4. Con số sau tên nốt giúp chúng ta phân biệt đúng dây và đúng âm vực.', 4);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (39, 1979, 'TEACHER_SPEECH', 'Khi đọc một bản nhạc, chúng ta còn cần chú ý đến tempo, khóa nhạc và nhịp.', 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (40, 1979, 'TEACHER_SPEECH', 'Tempo là tốc độ nhanh hoặc chậm của bản nhạc. Tempo có thể được ghi bằng số B P M; ví dụ, sáu mươi B P M chậm hơn một trăm hai mươi B P M. Khi tập đàn, bạn nên bắt đầu chậm, giữ đều nhịp rồi mới tăng tốc.', 6);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (41, 1979, 'TEACHER_SPEECH', 'Khóa Sol là ký hiệu thường đặt ở đầu khuông nhạc, giúp chúng ta xác định tên và độ cao của các nốt. Dấu khóa này bắt đầu từ dòng thứ hai của khuông nhạc, cho biết đó là vị trí của nốt Sol.', 7);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (42, 1979, 'TEACHER_SPEECH', 'Nhịp bốn phần tư nghĩa là mỗi ô nhịp có bốn phách và nốt đen được tính là một phách. Ta đếm đều: một, hai, ba, bốn. Phách một thường mạnh hơn các phách còn lại.', 8);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (43, 1979, 'TEACHER_SPEECH', 'Nhịp hai phần tư nghĩa là mỗi ô nhịp có hai phách và nốt đen cũng được tính là một phách. Ta đếm: một, hai; trong đó phách một mạnh và phách hai nhẹ hơn.', 9);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (44, 1979, 'TEACHER_SPEECH', 'Hiểu tempo và nhịp sẽ giúp chúng ta gảy đàn đúng tốc độ, đúng điểm rơi của phách. Khóa Sol giúp chúng ta đọc đúng nốt trên bản nhạc. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 10);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (45, 1979, 'TEACHER_SPEECH', 'Bây giờ chúng ta cùng luyện tập theo nhịp 4/4. Ta sẽ gảy nốt Sol2, đếm 1-2-3-4 cho mỗi ô nhịp. Hãy gảy nốt Sol2.', 11);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (46, 1979, 'TEACHER_SPEECH', 'Gảy nốt La2 giữ đều nhịp 4/4.', 12);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (47, 1979, 'TEACHER_SPEECH', 'Gảy nốt Đô3 giữ đều nhịp 4/4.', 13);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (48, 1979, 'TEACHER_SPEECH', 'Gảy nốt Rê3 giữ đều nhịp 4/4.', 14);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (49, 1979, 'TEACHER_SPEECH', 'Tiếp tục với nhịp 4/4: nốt Mi3.', 15);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (50, 1979, 'TEACHER_SPEECH', 'Rồi nốt Rê3, giữ nhịp đều.', 16);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (51, 1979, 'TEACHER_SPEECH', 'Nốt Đô3, giữ nhịp đều.', 17);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (52, 1979, 'TEACHER_SPEECH', 'Nốt La2, giữ nhịp đều.', 18);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (53, 1979, 'TEACHER_SPEECH', 'Giờ chuyển sang nhịp 2/4, nhanh gọn hơn: gảy nốt Sol2.', 19);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (54, 1979, 'TEACHER_SPEECH', 'Nốt La2 theo nhịp 2/4.', 20);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (55, 1979, 'TEACHER_SPEECH', 'Nốt Đô3 theo nhịp 2/4.', 21);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (56, 1979, 'TEACHER_SPEECH', 'Nốt Rê3 theo nhịp 2/4.', 22);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (57, 1979, 'TEACHER_SPEECH', 'Nốt Mi3 theo nhịp 2/4.', 23);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (58, 1979, 'TEACHER_SPEECH', 'Nốt Sol3 theo nhịp 2/4.', 24);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (59, 1979, 'TEACHER_SPEECH', 'Nốt Rê3 theo nhịp 2/4.', 25);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (60, 1979, 'TEACHER_SPEECH', 'Và cuối cùng nốt Đô3, giữ nhịp 2/4 thật đều.', 26);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (61, 1979, 'TEACHER_SPEECH', 'Tuyệt vời! Tóm lại: 17 dây đàn được chia thành âm vực trầm, trung và cao; tempo là tốc độ bài nhạc; khóa Sol xác định vị trí nốt trên khuông; nhịp 4/4 có 4 phách mỗi ô và nhịp 2/4 có 2 phách mỗi ô. Bạn đã hoàn thành bài học!', 27);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (1, 1980, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol1", "La1", "Đô2", "Rê2", "Mi2"], "durations": [1, 1, 1, 1, 2], "fingerings": ["2", "2", "2", "2", "2"], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (2, 1981, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol2", "La2", "Đô3", "Rê3", "Mi3"], "durations": [1, 1, 1, 1, 2], "fingerings": ["1", "1", "1", "1", "1"], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (3, 1982, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol3", "La3", "Đô4", "Rê4", "Mi4", "Sol4", "La4"], "durations": [1, 1, 1, 1, 1, 1, 2], "fingerings": ["3", "3", "3", "3", "3", "3", "3"], "cues": []}'::jsonb::jsonb, 1);
