INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (5, 1984, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol3", "La3", "Đô4", "Rê4", "Mi4", "Sol4", "La4"], "durations": [1.5, 1.5, 1.5, 1.5, 1.5, 1.5, 2], "fingerings": ["3", "2", "1", "3", "2", "1", "3"], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (62, 1985, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ luyện nửa đoạn đầu bài Lý cây đa.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (63, 1985, 'TEACHER_SPEECH', 'Hãy áp dụng các nốt và ngón gảy đã học để luyện nửa đầu bài Lý cây đa. Bạn nên tập chậm từng câu và đếm nhịp đều. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 2);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (6, 1985, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol2", "Sol2", "La2", "Đô3", "Rê3", "Mi3", "Rê3", "Đô3", "La2", "Sol2"], "durations": [1, 1, 0.5, 0.5, 1, 1, 0.5, 0.5, 1, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (64, 1986, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ tiếp tục luyện nửa đoạn cuối bài Lý cây đa.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (65, 1986, 'TEACHER_SPEECH', 'Hãy chú ý tên nốt, nhịp và ngón gảy của từng câu nhạc. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 2);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (7, 1986, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["La2", "Đô3", "Sol2", "La2", "Đô3", "Rê3", "Mi3", "Rê3", "Đô3", "La2", "Sol2", "La2", "Đô3", "Sol2"], "durations": [0.5, 0.5, 1, 0.5, 0.5, 1, 1, 0.5, 0.5, 1, 0.5, 0.5, 0.5, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (66, 1987, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ hoàn thiện bài Lý cây đa.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (67, 1987, 'TEACHER_SPEECH', 'Hãy ghép hai phần đã học để chơi hoàn chỉnh bài Lý cây đa. Bắt đầu chậm, gảy rõ tiếng và giữ nhịp đều. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 2);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (8, 1987, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol2", "Sol2", "La2", "Đô3", "Rê3", "Mi3", "Rê3", "Đô3", "La2", "Sol2", "La2", "Đô3", "Sol2"], "durations": [1, 1, 0.5, 0.5, 1, 1, 0.5, 0.5, 1, 1, 0.5, 0.5, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (68, 1988, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu kỹ thuật Á trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (69, 1988, 'TEACHER_SPEECH', 'Kỹ thuật Á là dùng ngón tay phải vuốt nhanh và liên tục qua nhiều dây để tạo thành một chuỗi âm thanh liền mạch.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (70, 1988, 'TEACHER_SPEECH', 'Á xuống là vuốt từ vùng dây có âm cao xuống vùng dây có âm thấp. Á lên là vuốt theo chiều ngược lại, từ âm thấp lên âm cao.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (71, 1988, 'TEACHER_SPEECH', 'Phần thực hành gồm hai lượt: Á xuống và Á lên. Ứng dụng sẽ nghe đàn thật, kiểm tra hướng vuốt, độ rộng và tính liên tục của chuỗi âm. Bây giờ chúng ta bắt đầu nhé!', 4);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (9, 1988, 'Thực hành', 'Thực hành', 'PRACTICE', 'glissando', 80, '{"practiceMode": "glissando", "rounds": [{"direction": "down", "stringSequence": [1, 2, 3, 4, 5, 6], "finger": "2"}, {"direction": "up", "stringSequence": [17, 16, 15, 14, 13, 12], "finger": "1"}]}'::jsonb::jsonb, 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (72, 1989, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu kỹ thuật nhấn trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (73, 1989, 'TEACHER_SPEECH', 'Kỹ thuật nhấn là dùng tay trái ấn dây ở phía bên trái của nhạn để nâng cao độ của âm thanh sau khi tay phải gảy dây.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (74, 1989, 'TEACHER_SPEECH', 'Nhờ kỹ thuật này, đàn Tranh có thể tạo ra những nốt không có sẵn trên dây. Ví dụ, nhấn dây La để lên nốt Si, hoặc nhấn dây Mi để lên nốt Fa.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (75, 1989, 'TEACHER_SPEECH', 'Khi thực hiện, tay phải gảy dây trước, sau đó tay trái nhấn nhẹ và đều đến đúng cao độ. Không nhấn quá mạnh vì tiếng đàn có thể bị gắt hoặc cao độ bị lệch. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 4);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (10, 1989, 'Thực hành', 'Thực hành', 'PRACTICE', 'press', 80, '{"practiceMode": "press", "noteSequence": ["Mi2", "Fa2", "La2", "Si2", "Mi3", "Fa3", "La3", "Si3"], "techniqueCues": ["press", "", "press", "", "press", "", "press", ""]}'::jsonb::jsonb, 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (76, 1990, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu kỹ thuật song thanh trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (77, 1990, 'TEACHER_SPEECH', 'Song thanh là kỹ thuật gảy để hai nốt cùng phát ra một lúc. Song thanh truyền thống thường sử dụng quãng tám; các nhạc sĩ hiện đại còn kết hợp thêm những quãng khác.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (78, 1990, 'TEACHER_SPEECH', 'Trong bài này, chúng ta dùng ngón 1 và ngón 2 của tay phải để gảy đồng thời hai dây.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (79, 1990, 'TEACHER_SPEECH', 'Khi thực hiện, hai tiếng phải phát ra đồng thời, không bị chênh nhau và có âm lượng cân bằng. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 4);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (11, 1990, 'Thực hành', 'Thực hành', 'PRACTICE', 'double_stop', 80, '{"practiceMode": "double_stop", "fingerings": ["1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2", "1 + 2"]}'::jsonb::jsonb, 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (80, 1991, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu kỹ thuật rung dây trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (81, 1991, 'TEACHER_SPEECH', 'Kỹ thuật rung dây tạo tiếng đàn ngân liên tục, mềm mại và giàu cảm xúc. Có hai kiểu rung chính: rung nhanh với biên độ hẹp và rung chậm với biên độ rộng. Trong bài này, chúng ta luyện kiểu rung để thể hiện nét vui của giai điệu.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (82, 1991, 'TEACHER_SPEECH', 'Sau khi tay phải gảy dây, tay trái rung ngay để tiếng đàn không bị ngắt quãng. Dùng ngón trỏ và ngón giữa tay trái đặt nhẹ lên dây ở phía bên trái nhạn, cách nhạn khoảng mười xen-ti-mét. Không tỳ mạnh xuống dây vì có thể làm sai cao độ.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (83, 1991, 'TEACHER_SPEECH', 'Giữ cổ tay và các ngón tay mềm mại. Dùng hai ngón tay nhồi dây nhẹ nhàng lên xuống, đều tay, để tiếng rung tự nhiên và kéo dài. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 4);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (12, 1991, 'Thực hành', 'Thực hành', 'PRACTICE', 'vibrato', 80, '{"practiceMode": "vibrato", "noteSequence": ["Sol2", "La2", "Đô3", "Rê3", "Mi3", "Sol3", "La3"], "techniqueCues": ["vibrato", "vibrato", "vibrato", "vibrato", "vibrato", "vibrato", "vibrato"]}'::jsonb::jsonb, 5);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (13, 1992, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Rê3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "La2", "Sol2"], "durations": [0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 1, 0.5, 0.5, 0.5, 0.5, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 1);
