INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (15, 1994, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Rê3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "La2", "Sol2", "Rê3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "Đô3", "Mi3", "Rê3", "Đô3", "Sol2", "La2", "Mi3", "Mi3", "Rê3", "Mi3", "Rê3", "Mi3", "Sol3", "Mi3", "Rest", "Mi3", "Mi3", "Rê3", "Đô3", "Mi3", "Rê3", "Rê3", "Đô3", "La2", "Đô3", "Đô3", "La2", "Đô3", "La2", "Sol2", "Sol2", "La2", "Mi3", "Sol3", "Sol3", "Mi3", "Sol3", "Sol3", "Mi3", "Rê3", "Đô3", "Đô3", "Rê3", "Đô3", "Rê3", "Mi3", "Rê3", "Rê3", "Đô3", "Rê3", "Đô3", "Rê3", "Đô3", "Đô3", "La2", "Đô3", "Rê3", "Rê3", "Rê3"], "durations": [0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 1, 0.5, 0.5, 0.5, 0.5, 2, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 1, 1, 0.5, 0.5, 2, 0.5, 0.5, 1, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 3, 1, 1, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (16, 1995, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Đô2", "Rê2", "Mi2", "Rê2", "Đô2", "La2", "Sol2", "Sol2", "Đô2", "Rê2", "Mi2", "Sol2", "Mi2", "Rê2", "Đô2", "Đô2", "La2", "Sol2", "Sol2", "Sol2", "Đô2", "Rê2", "Đô2", "Sol2"], "durations": [0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1, 0.5, 0.5, 1], "fingerings": [], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (17, 1996, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Đô2", "Đô2", "Rê2", "Rê2", "Mi2", "Mi2", "Sol2", "Sol2"], "durations": [2, 2, 2, 2, 2, 2, 2, 2], "fingerings": [], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (18, 1997, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Sol1", "La1", "Đô2", "Rê2", "Mi2", "Sol2", "La2", "Đô3", "Rê3", "Mi3", "Sol3", "La3", "Đô4", "Rê4", "Mi4", "Sol4", "La4"], "durations": [], "fingerings": [], "cues": []}'::jsonb::jsonb, 1);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (19, 1998, 'Thực hành', 'Thực hành', 'PRACTICE', 'note_sequence', 80, '{"practiceMode": "note_sequence", "noteSequence": ["Đô2+Mi2+Sol2", "La1+Đô2+Mi2", "Đô2+Mi2+Sol2", "La1+Đô2+Mi2", "Đô2+Mi2+Sol2", "La1+Đô2+Mi2", "Đô2+Mi2+Sol2", "La1+Đô2+Mi2", "Đô2+Mi2+Sol2", "La1+Đô2+Mi2", "La1+Đô2+Mi2", "Đô2+Mi2+Sol2", "Đô2+Mi2+Sol2", "La1+Đô2+Mi2"], "durations": [], "fingerings": ["1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3"], "cues": ["circle", "circle", "circle", "circle", "triangle", "triangle", "triangle", "triangle", "circle", "circle", "triangle", "triangle", "circle", "triangle"]}'::jsonb::jsonb, 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (84, 1999, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu kỹ thuật vê trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (85, 1999, 'TEACHER_SPEECH', 'Kỹ thuật vê là gảy luân phiên thật nhanh và liên tục bằng hai ngón tay phải để tạo tiếng đàn ngân dài, dày và liền mạch.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (86, 1999, 'TEACHER_SPEECH', 'Có hai cách vê cơ bản. Vê một dây là hai ngón thay phiên gảy trên cùng một dây.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (87, 1999, 'TEACHER_SPEECH', 'Vê quãng tám là hai ngón thay phiên gảy trên hai dây cùng tên nốt nhưng khác quãng, ví dụ nốt Đô thấp và nốt Đô cao.', 4);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (88, 1999, 'TEACHER_SPEECH', 'Kỹ thuật vê thường dùng để giữ âm, làm nổi bật giai điệu và tăng cảm xúc cho câu nhạc. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 5);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (20, 1999, 'Thực hành', 'Thực hành', 'PRACTICE', 'tremolo', 80, '{"practiceMode": "tremolo", "noteSequence": ["Đô2", "Mi2", "Sol2", "Mi2", "Đô2", "Mi2", "Sol2", "Mi2"], "fingerings": ["2", "2", "2", "2", "2", "2", "2", "2"]}'::jsonb::jsonb, 6);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (89, 2000, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu hợp âm ba âm cơ bản trên đàn Tranh.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (90, 2000, 'TEACHER_SPEECH', 'Hợp âm ba âm là ba nốt khác nhau được gảy cùng lúc, tạo âm thanh đầy đặn hơn một nốt đơn.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (91, 2000, 'TEACHER_SPEECH', 'Trong bài này, chúng ta làm quen với hai hợp âm cơ bản để hiểu thêm về cách hòa âm trên đàn Tranh.', 3);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (92, 2000, 'TEACHER_SPEECH', 'Phần hợp âm ba âm này được học để bạn biết thêm về khả năng tạo âm thanh hợp âm của đàn Tranh; nội dung này không áp dụng vào kiến thức nhạc cụ dân tộc Việt Nam. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 4);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (21, 2000, 'Thực hành', 'Thực hành', 'PRACTICE', 'triad', 80, '{"practiceMode": "triad", "fingerings": ["1", "2", "1", "2", "1", "1", "1", "2", "1", "2", "1 + 2 + 3"]}'::jsonb::jsonb, 5);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (93, 2001, 'TEACHER_SPEECH', 'Chào bạn! Trong bài học này, chúng ta sẽ cùng tìm hiểu hợp âm Đô trưởng.', 1);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (94, 2001, 'TEACHER_SPEECH', 'Hợp âm Đô trưởng gồm ba nốt: Đô, Mi và Sol.', 2);
INSERT INTO lesson_contents (id, lesson_id, content_type, content_text, order_index) VALUES (95, 2001, 'TEACHER_SPEECH', 'Khi gảy, hãy cố gắng để cả ba nốt vang lên cùng lúc và có âm lượng cân bằng. Bây giờ, chúng ta cùng bắt đầu phần thực hành nhé!', 3);
INSERT INTO exercises (id, lesson_id, title, description, exercise_type, practice_mode, pass_threshold, config_json, order_index) VALUES (22, 2001, 'Thực hành', 'Thực hành', 'PRACTICE', 'triad', 80, '{"practiceMode": "triad", "fingerings": ["1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3", "1 + 2 + 3"]}'::jsonb::jsonb, 4);
